const J=JSON.stringify; const R=(n)=>Math.floor(Math.random()*n); const pick=(a)=>a[R(a.length)];
let fails=0; const check=(label,a,b)=>{ if(J(a)!==J(b)){ fails++; if(fails<6) console.log("FAIL",label,J(a),J(b)); } };
// --- examples
check("ex1", M.applyPatch({}, {size:"compact"}), compatMerge({}, {size:"compact"}));
check("ex2", M.applyPatch({accent:null},{accent:null,theme:"blue"}), compatMerge({accent:null},{accent:null,theme:"blue"}));
check("title0", M.toTitle(""), compatStartCase(""));
check("title1", M.toTitle("Size UserUsersize."), compatStartCase("Size UserUsersize."));
check("lookup1", M.toLookup([["choi",64],["jung",-4],["jung",17],["kim",70],["choi",17],["jung",75]]), compatFromPairs([["choi",64],["jung",-4],["jung",17],["kim",70],["choi",17],["jung",75]]));
check("lookup2", M.toLookup([["lee",57],["jung",27],["kim",91]]), compatFromPairs([["lee",57],["jung",27],["kim",91]]));
// --- random titles (ASCII letters, digits, space, -, _, .; len 0..40)
const TC="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789 -_.";
for(let i=0;i<30000;i++){ let s=""; const n=R(41); for(let j=0;j<n;j++) s+=TC[R(TC.length)]; check("title-rand:"+s, M.toTitle(s), compatStartCase(s)); }
// --- random lookups (0..8 pairs, lowercase names, may repeat, ints)
for(let i=0;i<30000;i++){ const n=R(9); const pairs=Array.from({length:n},()=>[pick(["a","bb","choi","jung","kim","lee"]), R(400)-200]); check("lookup-rand", M.toLookup(pairs), compatFromPairs(pairs)); }
// --- random applyPatch in range (copy of generator logic, kind-consistent)
const scalar=()=>pick([()=>pick(["a","xy","zz"]),()=>R(100)-50,()=>Math.random()<0.5,()=>null])();
const kindOf=(v)=>v===null?"null":Array.isArray(v)?"array":typeof v;
function arr(d){ const n=R(4); return Math.random()<0.5? Array.from({length:n},()=>scalar()) : Array.from({length:n},()=>obj(d-1)); }
function value(d){ const k=R(d>1?5:4); if(k===1) return arr(d); if(k===4) return obj(d-1); return scalar(); }
function obj(d){ const o={}; const n=R(4); for(let i=0;i<n;i++) o[pick(["k1","k2","k3","size","accent","theme"])]=value(d); return o; }
function patchFor(base,d){ const p={}; for(const k of Object.keys(base)){ if(Math.random()<0.4) continue; const bv=base[k], kb=kindOf(bv);
  if(kb==="object") p[k]=patchFor(bv,d-1);
  else if(kb==="array"){ const isObj=bv.length&&typeof bv[0]==="object"&&bv[0]!==null; p[k]=Array.from({length:R(4)},(_,i)=> isObj ? ((i<bv.length&&bv[i]&&typeof bv[i]==="object"&&!Array.isArray(bv[i]))?patchFor(bv[i],d-1):obj(1)) : scalar()); }
  else p[k]=scalar(); }
  for(const nk of ["n1","n2","size"]) if(!(nk in base)&&Math.random()<0.5) p[nk]=value(d);
  return p; }
for(let i=0;i<30000;i++){ const base=obj(3); const patch=patchFor(base,3);
  const b1=structuredClone(base), b2=structuredClone(base);
  check("patch-rand", M.applyPatch(b1,structuredClone(patch)), compatMerge(b2,structuredClone(patch))); }
console.log("total failures:", fails);
EOF
